return [{
  json: {
    firma: 'Smart Immo Concept',
    ansprechpartner: 'Kai Weber',
    leistung: 'unabhängige Baufinanzierungs-Vermittlung (Vergleich vieler Banken), Anschlussfinanzierung, Förderberatung (KfW/Landesprogramme)',
